private String sanitize(String input) {
    // Whitelist of allowed characters
    String allowedChars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

    // Remove characters not in the whitelist
    return input.chars()
