        if (user != null && user.getPassword().equals(password)) {
            return "SessionToken";
        }
        return null;
    }


    public void logoutUser(String sessionToken) {
        userRepository.deleteBySessionToken(sessionToken);
        logger.info("User logged out: {}", sessionToken);
    }


    public void saveSessionToken(String sessionToken, String userId) {
        User user = userRepository.findById(userId);
        if (user != null) {
            user.setSessionToken(sessionToken);
            userRepository.save(user);
        }
    }


    public void clearSessionToken(String sessionToken) {
        userRepository.deleteBySessionToken(sessionToken);
    }

