        // Ensure the first tag is "Envelope"
        if (!"Envelope".equals(xmlStreamReader.getLocalName())) {
            LOG.debug("First tag in SOAP request is incorrect: '" + xmlStreamReader.getLocalName() + "' (expected 'Envelope')");
