 * @param path Path to be adjusted
 * @return Adjusted path or null if invalid
 */
protected String normalize(String path) {
    if (path == null) {
        return null;
    }
    String normalizedPath = path;
    // Handle paths starting with double-slash
    if (normalizedPath.startsWith("//")) {
        normalizedPath = normalizedPath.replace("//", "/");
    }
    // Handle paths starting with dot-slash
    if (normalizedPath.startsWith("./")) {
        normalizedPath = normalizedPath.replaceFirst("./", "/");
    }
    // Replace backslashes with forward slashes and ensure path starts with a slash
    if (normalizedPath.indexOf('\\') >= 0) {
        normalizedPath = normalizedPath.replace('\\', '/');
    }
    // Eliminate parent directory path sequences
    while (true) {
        int parentDirIndex = normalizedPath.indexOf("/../");
        if (parentDirIndex < 0) {
            break;
        }
        if (parentDirIndex == 0) {
            // This would create a negative path
            return null;
        }
        int lastSlashIndex = normalizedPath.lastIndexOf('/', parentDirIndex - 1);
        normalizedPath = normalizedPath.substring(0, lastSlashIndex) + normalizedPath.substring(parentDirIndex + 3);
    }
    // Simplify current directory references
    normalizedPath = evaluateNormalizedPathWithSinglePoint(normalizedPath);
    // Ensure path starts with a forward slash
    if (!normalizedPath.startsWith("/")) {
        normalizedPath = "/" + normalizedPath;
    }
    // Return the standardized path
    return normalizedPath;
}

